use serde_json::{json,Value};use std::{fs,io::{Read,Write,BufRead,BufReader},net::TcpListener,process::{Command,Stdio},os::unix::fs::PermissionsExt,sync::{Arc,atomic::{AtomicBool,Ordering},mpsc},thread,time::{Instant,Duration}};
#[test]
fn watch_delivers_subscription_message_before_poll_and_stops_on_hide(){
 let root=std::env::temp_dir().join(format!("t3-live-test-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let token=root.join("token");fs::write(&token,"synthetic-token").unwrap();fs::set_permissions(&token,fs::Permissions::from_mode(0o600)).unwrap();let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let config=root.join("env.json");fs::write(&config,json!({"environments":[{"id":"fixture","name":"Fixture","base_url":base,"token_file":token}]}).to_string()).unwrap();let stop=Arc::new(AtomicBool::new(false));let server_stop=stop.clone();let socket_closed=Arc::new(AtomicBool::new(false));let closed=socket_closed.clone();
 let server=thread::spawn(move||{while !server_stop.load(Ordering::Relaxed){if let Ok((mut s,_))=listener.accept(){let closed=closed.clone();thread::spawn(move||{s.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut peek=[0;1024];let n=s.peek(&mut peek).unwrap_or(0);let request=String::from_utf8_lossy(&peek[..n]);if request.starts_with("GET /ws") {let mut ws=tungstenite::accept(s).unwrap();let req:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();assert_eq!(req["tag"],"orchestration.subscribeThread");assert_eq!(req["payload"]["afterSequence"],0);assert_eq!(req["payload"]["acceptCompactTurnItems"],true);ws.send(tungstenite::Message::Text(json!({"_tag":"Chunk","requestId":"1","values":[{"kind":"synchronized"}]}).to_string().into())).unwrap();let _=ws.read();thread::sleep(Duration::from_millis(90));let update=json!({"kind":"event","sequence":1,"event":{"type":"message.updated","payload":{"id":"new","role":"assistant","text":"streamed immediately","createdAt":2000,"attachments":[]}}});ws.send(tungstenite::Message::Text(json!({"_tag":"Chunk","requestId":"1","values":[update.clone(),update]}).to_string().into())).unwrap();loop{match ws.read(){Ok(tungstenite::Message::Close(_))|Err(_)=>break,Ok(tungstenite::Message::Text(t))=>{let v:Value=serde_json::from_str(&t).unwrap();if v["_tag"]=="Interrupt"{break}},_=>{}}}closed.store(true,Ordering::Relaxed);
 }else{let mut data=[0;8192];let _=s.read(&mut data);let body=if request.contains("/bounded"){json!({"snapshotSequence":0,"projection":{"thread":{"id":"one"},"messages":[{"id":"old","role":"user","text":"hello","createdAt":1000}],"runs":[],"turnItems":[]}})}else{json!({"threads":[{"id":"one","title":"One","updatedAt":1000}],"projects":[]})};let body=body.to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();}});}else{thread::sleep(Duration::from_millis(5));}}});
 let mut child=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).arg("watch").env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",config).env_remove("OPENCODE_API_KEY").env_remove("OPENCODE_GO_API_KEY").env_remove("KIMI_CODING_API_KEY").env_remove("NOUS_API_KEY").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();let mut input=child.stdin.take().unwrap();let (tx,rx)=mpsc::channel();let output=child.stdout.take().unwrap();thread::spawn(move||for line in BufReader::new(output).lines().map_while(Result::ok){if let Ok(v)=serde_json::from_str::<Value>(&line){let _=tx.send(v);}});
 writeln!(input,"{}",json!({"op":"visible","value":true})).unwrap();let start=Instant::now();writeln!(input,"{}",json!({"op":"select","environment":"fixture","thread":"one","serial":73})).unwrap();loop{let v=rx.recv_timeout(Duration::from_secs(3)).unwrap();if v["type"]=="messages"&&v["data"]["result"]["messages"].as_array().is_some_and(|ms|ms.iter().any(|m|m["text"]=="streamed immediately")){assert_eq!(v["data"]["serial"],73);assert_eq!(v["data"]["result"]["messages"].as_array().unwrap().len(),2);assert!(start.elapsed()<Duration::from_secs(2));break}}
 writeln!(input,"{}",json!({"op":"visible","value":false})).unwrap();for _ in 0..50{if socket_closed.load(Ordering::Relaxed){break}thread::sleep(Duration::from_millis(10));}assert!(socket_closed.load(Ordering::Relaxed));writeln!(input,"{}",json!({"op":"quit"})).unwrap();child.wait().unwrap();stop.store(true,Ordering::Relaxed);server.join().unwrap();fs::remove_dir_all(root).unwrap();
}
